// Collapse active client_config rows into one routing object for this run.
const run = $('Set Run Context').first().json;
const rows = $input.all()
  .map(i => i.json)
  .filter(j => j && (j.client_code || (j.fields && j.fields.client_code)))
  .map(j => j.fields || j);

const clients = [];
const problems = [];
for (const f of rows) {
  const code = String(f.client_code).trim().toUpperCase();
  let patterns = {};
  try {
    patterns = JSON.parse(f.source_patterns_json || '{}');
  } catch (e) {
    problems.push(code + ': source_patterns_json is not valid JSON, client skipped');
    continue;
  }
  if (!Object.keys(patterns).length) {
    problems.push(code + ': source_patterns_json has no patterns, client skipped');
    continue;
  }
  clients.push({ client_code: code, client_name: f.client_name || code, patterns });
}

return [{ json: {
  run_id: run.run_id,
  active_client_count: clients.length,
  clients,
  config_problems: problems
} }];

// Route each Inbox file to a client and source type, then decide what to do with it.
// file_key = Drive file id + content version, so the same file is never received twice,
// while a re-uploaded file with new content is recognised as a revision.
const ctx = $('Build Client Routes').first().json;
const run = $('Set Run Context').first().json;

const files = $('List Inbox Files').all()
  .map(i => i.json)
  .filter(f => f && f.id && f.trashed !== true);

const existing = $input.all()
  .map(i => i.json)
  .filter(j => j && (j.file_key || (j.fields && j.fields.file_key)))
  .map(j => j.fields || j);
const seenKeys = new Set(existing.map(r => r.file_key));
const seenIds = new Set(existing.map(r => r.file_id));

const out = [];
for (const f of files) {
  const name = String(f.name || '');
  const version = f.md5Checksum || f.modifiedTime || 'unversioned';
  const fileKey = f.id + '|' + version;

  const matches = [];
  for (const c of ctx.clients) {
    for (const [sourceType, pattern] of Object.entries(c.patterns)) {
      let re;
      try { re = new RegExp(pattern, 'i'); } catch (e) { continue; }
      if (re.test(name)) matches.push({ client_code: c.client_code, source_type: sourceType });
    }
  }

  let client = 'UNKNOWN', source = 'unknown', action, status, issueType = '', errorSummary = '';
  if (seenKeys.has(fileKey)) {
    action = 'already_received';
    status = 'already_received';
    if (matches.length === 1) { client = matches[0].client_code; source = matches[0].source_type; }
  } else if (matches.length === 1) {
    client = matches[0].client_code; source = matches[0].source_type;
    action = 'new'; status = 'received';
  } else if (matches.length === 0) {
    action = 'reject_unrecognised'; status = 'rejected_unrecognised';
    issueType = 'unrecognised_file';
    errorSummary = 'Filename does not match any active client source pattern';
  } else {
    action = 'reject_unrecognised'; status = 'rejected_unrecognised';
    issueType = 'ambiguous_file_route';
    errorSummary = 'Filename matches multiple patterns: ' + matches.map(m => m.client_code + '/' + m.source_type).join(', ');
  }

  out.push({ json: {
    run_id: run.run_id,
    client_code: client,
    source_type: source,
    file_id: f.id,
    file_name: name,
    mime_type: f.mimeType || '',
    size_bytes: Number(f.size) || 0,
    modified_time: f.modifiedTime || '',
    md5_checksum: f.md5Checksum || '',
    file_key: fileKey,
    action,
    status,
    is_revision: !seenKeys.has(fileKey) && seenIds.has(f.id),
    issue_type: issueType,
    error_summary: errorSummary,
    received_at: new Date().toISOString()
  } });
}
return out;

// Run summary for the intake stage. Later modules update this same run_id row.
const ctx = $('Build Client Routes').first().json;
const run = $('Set Run Context').first().json;
const rows = $('Classify And Decide').all().map(i => i.json).filter(r => r && r.file_id);
const count = a => rows.filter(r => r.action === a).length;

const notes = [];
if (rows.length === 0) notes.push('Inbox empty: zero-row run');
if (ctx.config_problems.length) notes.push('Config warnings: ' + ctx.config_problems.join(' | '));

return [{ json: {
  run_id: run.run_id,
  execution_mode: run.execution_mode,
  started_at: run.started_at,
  finished_at: new Date().toISOString(),
  status: ctx.config_problems.length ? 'intake_complete_with_warnings' : 'intake_complete',
  active_clients: ctx.active_client_count,
  files_listed: rows.length,
  files_new: count('new'),
  files_already_received: count('already_received'),
  files_unrecognised: count('reject_unrecognised'),
  notes: notes.join(' ; ')
} }];
